  align-items: center;
  height: 68px;
}
.brand {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 22px;
  letter-spacing: .02em;
}
.brand .dot { color: var(--accent); }
.nav {
  display: flex;
  gap: 28px;
  justify-content: center;
}
.nav a {
  font-size: 14px;
  color: var(--ink-soft);
  position: relative;
  padding: 6px 2px;
  transition: color .2s;
}
.nav a:hover { color: var(--ink); }
.nav a.active { color: var(--ink); }
.nav a.active::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -2px;
  height: 2px;
  background: var(--ink);
}
.actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
  position: relative;
  transition: background .2s;
}
.icon-btn:hover { background: var(--chip); }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #fff;
  font-size: 10px;
  min-width: 16px;
  height: 16px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  font-weight: 600;
}

/* ---------- Hero ---------- */
.hero {
  padding: 36px 0 60px;
}
.hero-card {
  position: relative;
  border-radius: 22px;
  overflow: hidden;
  background:
    linear-gradient(120deg, rgba(0,0,0,.55) 0%, rgba(0,0,0,.15) 45%, rgba(0,0,0,0) 70%),
    url("https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1800&q=80") center/cover no-repeat;
  min-height: 540px;
  display: flex;
  align-items: flex-end;
  padding: 56px;
  color: #fff;
}
.hero-content { max-width: 560px; }
.eyebrow {
  display: inline-block;
  font-size: 12px;
  letter-spacing: .18em;
  text-transform: uppercase;
  background: rgba(255,255,255,.18);
  border: 1px solid rgba(255,255,255,.35);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 22px;
  backdrop-filter: blur(4px);
}
.hero h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(40px, 5.5vw, 68px);
  line-height: 1.02;
  letter-spacing: -.01em;
  margin: 0 0 18px;
}
.hero h1 em {
  font-style: italic;
  font-weight: 400;
  color: #ffd9cf;
}
.hero p {
  font-size: 17px;
  color: rgba(255,255,255,.86);
  margin: 0 0 28px;
  max-width: 460px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: .01em;
  transition: transform .15s ease, background .2s, color .2s, border-color .2s;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: #ff4421; }
.btn-light { background: #fff; color: var(--ink); }
.btn-ghost { background: transparent; color: #fff; border: 1px solid rgba(255,255,255,.6); }
.btn-ghost:hover { background: rgba(255,255,255,.12); }
.btn-dark { background: var(--ink); color: #fff; }
.btn-outline { background: transparent; color: var(--ink); border: 1px solid var(--ink); }
.btn-outline:hover { background: var(--ink); color: #fff; }

/* ---------- Section header ---------- */
.section { padding: 56px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}
.section-head .label {
  font-size: 12px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 8px;
}
.section-head h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(28px, 3.4vw, 40px);
  letter-spacing: -.01em;
  margin: 0;
}
.section-head .head-link {
  font-size: 14px;
  color: var(--ink);
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
}

/* ---------- Categories ---------- */
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.cat {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 14px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  transition: transform .2s, box-shadow .2s, border-color .2s;
  cursor: pointer;
}
.cat:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: #e0ddd3; }
.cat-icon {
  width: 56px; height: 56px;
  border-radius: 999px;
  background: var(--chip);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
}
.cat-name { font-size: 13px; font-weight: 500; }
.cat-count { font-size: 11px; color: var(--muted); }

/* ---------- Filter chips (featured) ---------- */
.chips {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}
.chip {
  font-size: 13px;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--chip);
  color: var(--ink-soft);
  transition: background .2s, color .2s;
}
.chip:hover { background: #e7e3d8; }
.chip.active { background: var(--ink); color: #fff; }

/* ---------- Product grid ---------- */
.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.product {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .2s ease, box-shadow .2s;
}
.product:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: #efece6;
  overflow: hidden;
}
.product-media img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform .6s ease;
}
.product:hover .product-media img { transform: scale(1.04); }
.tag {
  position: absolute;
  top: 12px; left: 12px;
  font-size: 11px;
  letter-spacing: .08em;
  text-transform: uppercase;
  background: #fff;
  color: var(--ink);
  padding: 5px 9px;
  border-radius: 999px;
  font-weight: 600;
}
.tag.sale { background: var(--sale); color: #fff; }
.tag.new { background: var(--ink); color: #fff; }
.wish {
  position: absolute;
  top: 12px; right: 12px;
  background: rgba(255,255,255,.92);
  width: 34px; height: 34px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background .2s, color .2s;
}
.wish:hover { background: #fff; color: var(--accent); }
.wish.active { color: var(--accent); }
.product-add {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  background: var(--ink);
  color: #fff;
  padding: 11px 12px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  text-align: center;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .25s, transform .25s, background .2s;
}
.product:hover .product-add { opacity: 1; transform: translateY(0); }
.product-add:hover { background: var(--accent); }
.product-body { padding: 14px 4px 6px; }
.product-cat { font-size: 11px; color: var(--muted); letter-spacing: .12em; text-transform: uppercase; }
.product-name {
  font-size: 15px;
  font-weight: 500;
  margin: 4px 0 6px;
  color: var(--ink);
}
.product-price {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
}
.price-now { font-weight: 600; }
.price-was { text-decoration: line-through; color: var(--muted); font-size: 13px; }
.price-off { color: var(--sale); font-size: 12px; font-weight: 600; }
.product-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 6px;
  font-size: 12px;
  color: var(--muted);
}
.swatches { display: flex; gap: 5px; }
.swatch { width: 12px; height: 12px; border-radius: 999px; border: 1px solid rgba(0,0,0,.1); }
.rating { display: inline-flex; align-items: center; gap: 4px; }

/* ---------- Deals strip ---------- */
.deals {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 18px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  min-height: 260px;
  padding: 28px;
  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.deal-bg {
  position: absolute; inset: 0;
  background-size: cover;
  background-position: center;
}
.deal::before {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,.05) 0%, rgba(0,0,0,.55) 100%);
}
.deal > * { position: relative; z-index: 1; }
.deal-1 .deal-bg { background-image: url("https://images.unsplash.com/photo-1485518882345-15568b007407?auto=format&fit=crop&w=1400&q=80"); }
.deal-2 .deal-bg { background-image: url("https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?auto=format&fit=crop&w=1200&q=80"); }
.deal-3 .deal-bg { background-image: url("https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1200&q=80"); }
.deal small {
  font-size: 11px;
  letter-spacing: .18em;
  text-transform: uppercase;
  opacity: .9;
}
.deal h3 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: 28px;
  line-height: 1.1;
  margin: 6px 0 4px;
}
.deal p { font-size: 14px; opacity: .9; margin: 0; max-width: 320px; }
.deal-foot { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.countdown {
  display: flex;
  gap: 6px;
  font-variant-numeric: tabular-nums;
}
.cd-cell {
  background: rgba(255,255,255,.18);
  border: 1px solid rgba(255,255,255,.3);
  backdrop-filter: blur(4px);
  border-radius: 8px;
  padding: 6px 8px;
  text-align: center;
  min-width: 44px;
}
.cd-num { font-size: 16px; font-weight: 600; line-height: 1; }
.cd-lbl { font-size: 9px; letter-spacing: .12em; text-transform: uppercase; opacity: .85; }

/* ---------- Editorial ---------- */
.editorial { background: #f3f1ea; }
.ed-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  gap: 22px;
}
.ed-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .2s, box-shadow .2s;
}
.ed-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.ed-card.feature { grid-row: span 2; }
.ed-media {
  aspect-ratio: 16/10;
  overflow: hidden;
  background: #ddd;
}
.ed-card.feature .ed-media { aspect-ratio: 4/3; }
.ed-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .6s; }
.ed-card:hover .ed-media img { transform: scale(1.05); }
.ed-body { padding: 22px 24px 24px; }
.ed-cat {
  font-size: 11px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
}
.ed-title {
  font-family: var(--serif);
  font-weight: 500;
  font-size: 22px;
  line-height: 1.2;
  margin: 8px 0 10px;
}
.ed-card.feature .ed-title { font-size: 30px; }
.ed-meta { font-size: 13px; color: var(--muted); }
.ed-excerpt { color: var(--ink-soft); font-size: 14px; margin: 0 0 12px; }

/* ---------- Promo banner ---------- */
.promo {
  background: var(--ink);
  color: #fff;
  border-radius: 22px;
  padding: 56px;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 40px;
  align-items: center;
}
.promo h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.05;
  margin: 0 0 14px;
}
.promo h2 em { color: #ffb6a3; font-style: italic; font-weight: 400; }
.promo p { color: rgba(255,255,255,.75); margin: 0 0 22px; max-width: 460px; }
.subscribe {
  display: flex;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 999px;
  padding: 6px;
  max-width: 460px;
}
.subscribe input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: #fff;
  padding: 10px 16px;
  font-size: 14px;
  font-family: inherit;
}
.subscribe input::placeholder { color: rgba(255,255,255,.5); }
.subscribe button {
  background: #fff;
  color: var(--ink);
  border-radius: 999px;
  padding: 10px 18px;
  font-size: 13px;
  font-weight: 500;
}
.subscribe button:hover { background: var(--accent); color: #fff; }
.promo-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}
.promo-stat {
  border: 1px solid rgba(255,255,255,.14);
  border-radius: var(--radius);
  padding: 22px;
}
.promo-stat .num {
  font-family: var(--serif);
  font-size: 32px;
  margin-bottom: 4px;
}
.promo-stat .lbl { font-size: 12px; color: rgba(255,255,255,.65); letter-spacing: .08em; text-transform: uppercase; }

/* ---------- Trust bar ---------- */
.trust {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 28px 0;
  margin: 24px 0 0;
}
.trust-item { display: flex; gap: 12px; align-items: center; }
.trust-ico { width: 40px; height: 40px; border-radius: 999px; background: var(--chip); display: inline-flex; align-items: center; justify-content: center; font-size: 18px; }
.trust h4 { margin: 0; font-size: 14px; }
.trust span { font-size: 12px; color: var(--muted); }

/* ---------- Footer ---------- */
.footer {
  padding: 56px 0 28px;
  color: var(--ink-soft);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 32px;
  padding-bottom: 36px;
  border-bottom: 1px solid var(--line);
}
.footer h5 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .14em;
  color: var(--ink);
  margin: 0 0 14px;
}
.footer ul { list-style: none; padding: 0; margin: 0; }
.footer ul li { margin-bottom: 8px; }
.footer ul li a { font-size: 14px; color: var(--ink-soft); }
.footer ul li a:hover { color: var(--ink); }
.foot-brand .brand { font-size: 24px; }
.foot-brand p { font-size: 14px; max-width: 320px; margin: 12px 0 18px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  border-radius: 999px;
  border: 1px solid var(--line);
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink);
  transition: background .2s, color .2s, border-color .2s;
}
.socials a:hover { background: var(--ink); color: #fff; border-color: var(--ink); }
.foot-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 22px;
  font-size: 13px;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(100px);
  background: var(--ink);
  color: #fff;
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 14px;
  z-index: 100;
  transition: transform .35s ease;
  box-shadow: var(--shadow-md);
}
.toast.show { transform: translateX(-50%) translateY(0); }

/* ---------- Responsive ---------- */
@media (max-width: 1080px) {
  .products { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .deals { grid-template-columns: 1fr 1fr; }
  .deal-1 { grid-column: 1 / -1; }
  .ed-grid { grid-template-columns: 1fr 1fr; }
  .ed-card.feature { grid-row: auto; grid-column: 1 / -1; }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .promo { grid-template-columns: 1fr; padding: 40px; }
  .trust { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .container { padding: 0 18px; }
  .nav { display: none; }
  .hero-card { padding: 32px; min-height: 460px; }
  .products { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .deals { grid-template-columns: 1fr; }
  .deal-1 { grid-column: auto; }
  .ed-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .trust { grid-template-columns: 1fr; }
  .product-add { opacity: 1; transform: none; } /* always visible on mobile */
}

