        <Deals/>
        <Editorial/>
        <Promo onSubscribe={subscribe}/>
        <Trust/>
      </main>
      <Footer/>
      <Toast msg={toast}/>
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App/>);
