  return (
    <article className="product">
      <div className="product-media">
        <img src={p.img} alt={p.name} loading="lazy"/>
        {p.tag === "sale" && <span className="tag sale">−{off}% Sale</span>}
        {p.tag === "new" && <span className="tag new">New</span>}
        <button
          className={`wish ${wish ? "active" : ""}`}
          aria-label="Add to wishlist"
          onClick={() => onWish(p.id)}
        >
          <Icon name={wish ? "heart-fill" : "heart"} size={16}/>
        </button>
        <button className="product-add" onClick={() => onAdd(p)}>+ Add to Bag</button>
      </div>
      <div className="product-body">
