const Countdown = () => {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 38 + 12000, []);
  const [t, setT] = useState(target - Date.now());
  useEffect(() => {
    const id = setInterval(() => setT(Math.max(0, target - Date.now())), 1000);
    return () => clearInterval(id);
  }, [target]);
  const h = Math.floor(t / 3600000);
  const m = Math.floor((t % 3600000) / 60000);
  const s = Math.floor((t % 60000) / 1000);
  const cell = (n, l) => (
    <div className="cd-cell"><div className="cd-num">{String(n).padStart(2, "0")}</div><div className="cd-lbl">{l}</div></div>
  );
  return <div className="countdown">{cell(h, "Hrs")}{cell(m, "Min")}{cell(s, "Sec")}</div>;
};

