/* ----------------------- App ----------------------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [toast, setToast] = useState("");

  useEffect(() => {
    if (!toast) return;
    const id = setTimeout(() => setToast(""), 2200);
    return () => clearTimeout(id);
  }, [toast]);

  const addToCart = (p) => {
    setCart(c => [...c, p.id]);
    setToast(`Added "${p.name}" to bag`);
  };
  const toggleWish = (id) => {
    setWishlist(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);
  };
  const subscribe = (email) => setToast(`Welcome aboard — confirmation sent to ${email}`);

  return (
    <>
      <Announcement/>
      <Header cartCount={cart.length} wishCount={wishlist.length} onCart={() => setToast(`You have ${cart.length} item(s) in your bag`)}/>
      <main>
        <Hero/>
        <Categories/>
        <Featured wishlist={wishlist} onWish={toggleWish} onAdd={addToCart}/>
        <Deals/>
        <Editorial/>
        <Promo onSubscribe={subscribe}/>
        <Trust/>
      </main>
      <Footer/>
      <Toast msg={toast}/>
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App/>);
